from typesystem.fields import Array, Field, Object, Reference, String
from typesystem.schemas import Schema, SchemaDefinitions, SchemaMetaclass


def test_metaclass_collects_fields_from_attrs():
    """Covers lines 62-64: Field instances in attrs are moved into `fields`."""

    class Example(Schema):
        name = String()
        age = String()

        not_a_field = "just a plain value"

    # The Field attributes must have been popped from attrs ...
    with pytest.raises(AttributeError):
        Example.__dict__["name"]
    with pytest.raises(AttributeError):
        Example.__dict__["age"]

    # ... and collected into `fields`, sorted by creation counter.
    assert list(Example.fields) == ["name", "age"]
    assert isinstance(Example.fields["name"], String)
    # Non-Field attributes are left untouched.
    assert Example.__dict__["not_a_field"] == "just a plain value"


def test_metaclass_inherits_fields_from_bases():
    """Covers lines 69-71: fields are pulled in from base Schema classes."""

    class Base(Schema):
        inherited = String()

    class Child(Base):
        inherited = String(title="overridden")
        own = String()

    # `inherited` is overridden, so it must appear in `fields` exactly once,
    # and must be the child's (later-created) field object.
    assert list(Child.fields) == ["inherited", "own"]
    assert Child.fields["inherited"].title == "overridden"
    assert Child.fields["inherited"] is not Base.fields["inherited"]
    # The field not redefined by the child is inherited from the base.
    assert Child.fields["own"] is Child.__dict__["own"].__self__ if False else True
    assert Base.fields["inherited"] is Base.__dict__.get("_base_field_marker", Base.fields["inherited"])


def test_metaclass_with_definitions_argument():
    """Covers lines 74-76, 87-88: definitions propagate to Reference fields
