    # A non-Reference field is simply left alone (no crash, no assignment).
    assert not hasattr(WithReference.fields["plain"], "definitions") or (
        WithReference.fields["plain"].definitions is not definitions
        if hasattr(WithReference.fields["plain"], "definitions")
        else True
    )


